using System.Text.Json;
using Bms.Protocols.Realtime;
using Bms.Protocols.Transports;
using Microsoft.AspNetCore.SignalR;
using Microsoft.Extensions.Options;

namespace Bms.Api.Realtime;

/// <summary>
/// Receives the events Bms.Ingestion publishes to the internal MQTT bridge
/// topic (see MqttRealtimeNotifier) and re-broadcasts them over this
/// process's own SignalR hub. This is what lets a dashboard connected to
/// Bms.Api see telemetry/alerts/status changes that were actually
/// generated by the separate Ingestion process.
/// </summary>
public sealed class RealtimeBridgeService : BackgroundService
{
    private readonly MqttTransportAdapter _mqtt;
    private readonly RealtimeDelivery _delivery;
    private readonly IngestionHealthTracker _ingestionHealth;
    private readonly string _ingestionStatusTopic;
    private readonly ILogger<RealtimeBridgeService> _logger;

    public RealtimeBridgeService(
        MqttTransportAdapter mqtt,
        RealtimeDelivery delivery,
        IngestionHealthTracker ingestionHealth,
        IOptions<IngestionHealthOptions> ingestionHealthOptions,
        ILogger<RealtimeBridgeService> logger)
    {
        _mqtt = mqtt;
        _delivery = delivery;
        _ingestionHealth = ingestionHealth;
        _ingestionStatusTopic = ingestionHealthOptions.Value.StatusTopic;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _mqtt.MessageReceived += OnBridgeMessageAsync;

        try
        {
            await _mqtt.ConnectAsync(stoppingToken);
            await _mqtt.SubscribeAsync(MqttRealtimeNotifier.BridgeTopic, stoppingToken);
            await _mqtt.SubscribeAsync(_ingestionStatusTopic, stoppingToken);
            _logger.LogInformation("Real-time bridge subscribed to {Topic} and {StatusTopic}", MqttRealtimeNotifier.BridgeTopic, _ingestionStatusTopic);

            await Task.Delay(Timeout.Infinite, stoppingToken);
        }
        catch (OperationCanceledException)
        {
            // normal shutdown
        }
        finally
        {
            _mqtt.MessageReceived -= OnBridgeMessageAsync;
            await _mqtt.DisconnectAsync(CancellationToken.None);
        }
    }

    private async Task OnBridgeMessageAsync(Bms.Application.Abstractions.Transports.TransportMessage message, CancellationToken ct)
    {
        if (message.Address == _ingestionStatusTopic)
        {
            if (IngestionStatusMessage.TryParse(message.Payload) is { } status)
                _ingestionHealth.Update(status);
            else
                _logger.LogWarning("Unreadable ingestion status message on {Topic}", message.Address);
            return;
        }

        try
        {
            using var document = JsonDocument.Parse(message.Payload);
            var root = document.RootElement;
            var tenantId = root.GetProperty("tenantId").GetString();
            var eventName = root.GetProperty("eventName").GetString();
            var payload = root.GetProperty("payload").GetRawText();

            if (tenantId is null || eventName is null)
                return;

            var payloadElement = JsonDocument.Parse(payload).RootElement;
            if (Guid.TryParse(tenantId, out var tenant))
                await _delivery.SendAsync(tenant, eventName, payloadElement, ct);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Failed to relay real-time bridge message");
        }
    }
}
